#include <iostream>
#include <set>
#include <utility>
#include <limits>
#include <algorithm>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    long long minx = numeric_limits<long long>::max();
    long long miny = numeric_limits<long long>::max();
    long long maxx = numeric_limits<long long>::lowest();
    long long maxy = numeric_limits<long long>::lowest();
    long long area = 0;
    bool valid = n > 0;

    set<pair<long long, long long>> corners;

    auto toggle = [&](long long x, long long y) {
        pair<long long, long long> p{x, y};
        auto it = corners.find(p);
        if (it == corners.end())
            corners.insert(p);
        else
            corners.erase(it);
    };

    for (int i = 0; i < n; ++i) {
        long long x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;

        if (x1 >= x2 || y1 >= y2)
            valid = false;

        minx = min(minx, x1);
        miny = min(miny, y1);
        maxx = max(maxx, x2);
        maxy = max(maxy, y2);

        area += (x2 - x1) * (y2 - y1);

        toggle(x1, y1);
        toggle(x1, y2);
        toggle(x2, y1);
        toggle(x2, y2);
    }

    set<pair<long long, long long>> expected = {
        {minx, miny}, {minx, maxy}, {maxx, miny}, {maxx, maxy}
    };

    if (valid &&
        area == (maxx - minx) * (maxy - miny) &&
        corners == expected)
        cout << "YES\n";
    else
        cout << "NO\n";

    return 0;
}

